def viterbi(logA, logB, logpi, obs):
    d = logpi + logB[:, obs[0]]; back = []
    for o in obs[1:]:
        s = d[:, None] + logA; back.append(s.argmax(0)); d = s.max(0) + logB[:, o]
    path = [d.argmax()]
    for b in reversed(back): path.insert(0, b[path[0]])
    return path

