def ab(n, d, a, b, maxi):
    if d == 0 or terminal(n): return evaluate(n)
    for c in children(n):
        v = ab(c, d - 1, a, b, not maxi)
        if maxi: a = max(a, v)
        else: b = min(b, v)
        if a >= b: break
    return a if maxi else b

